from numbers_arth import load, ROB, RS
import os, pandas as pd
LO = pd.read_csv(os.path.join(RS, "S41_leaveout_ranges.csv")).set_index(["set", "cov"])
N = load()
def ci(v, src=None):
    r = (src or N["main"])[v]
    return f"RR {r['IRR']:.3f}; 95% CrI {r['lo']:.3f}-{r['hi']:.3f}"
def tci(t): return f"RR {t[0]:.3f}; 95% CrI {t[1]:.3f}-{t[2]:.3f}"
M = N["main"]; T1 = N["T1"]
S43 = lambda a, v: N["s43"][(a, v)]
dW = lambda a: N["s43_waic"][a] - N["waic_main"]
NCO = lambda o, v: N["nco"][(o, v)]
EN = {"전라남도": "South Jeolla", "경상북도": "North Gyeongsang", "경상남도": "South Gyeongsang", "충청남도": "South Chungcheong", "전라북도": "North Jeolla",
      "강원도": "Gangwon", "부산시": "Busan", "충청북도": "North Chungcheong", "대구시": "Daegu", "경기도": "Gyeonggi", "서울시": "Seoul", "인천시": "Incheon"}
def sidos(d, n):
    return ", ".join(f"{EN.get(k, k)} ({v})" for k, v in list(d.items())[:n])
TITLE = "Beyond population aging, arthritis care in Korea stays concentrated in southern and inland rural districts"
RUNNING = "Geography of arthritis care in Korea"
KEYWORDS = "Arthritis; Osteoarthritis; Spatio-temporal analysis; Rural health; Health services; Republic of Korea"

ROBL = {"moderate_pa_rate": "moderate physical activity", "public_pools_per_100k": "public swimming pools", "village_sports_facilities_per_100k": "village sports facilities",
        "older_leisure_facilities_per_1000": "senior leisure facilities", "older_single_household_share": "older single-person households", "regular_employee_share": "regular employment",
        "beds_per_1000": "hospital beds", "public_health_centre_use_rate": "public health center use"}

METHODS = [
("Data sources and outcome",
 f"This ecological study used annual numbers of people treated for arthritis (International Classification of Diseases, 10th revision [ICD-10] codes M00-M19 and M22-M25 as the principal diagnosis) from the Regional Medical Care Utilization Statistics of the National Health Insurance Service, 2011-2024 [@web:nhis2026regional]. The statistics cover National Health Insurance and Medical Aid beneficiaries, count care by date of service in all care settings, including Korean medicine clinics but excluding pharmacies, and attribute each person to the district of residence rather than to the treating facility. Each count is the number of unique persons treated in a year and therefore reflects treated prevalence (people under care), not incidence; the definition combines osteoarthritis (OA), rheumatoid and other inflammatory arthritis, gout, and other joint disorders. Districts were harmonized to {N['n_districts']} units with 2024 boundaries, giving {N['n_rows']:,} district-years. Mid-year resident registration populations by 5-year age group were used as denominators [@web:mois2026population]; the 2023 age block of one city (Changwon), which duplicated the 2022 block in the source file, was replaced with official totals and a residual reconstruction (Online Resource 1, Supplementary Methods)."),
("Age standardization",
 "Expected counts were obtained by indirect standardization: national age-specific treatment rates for the same diagnoses in ten age groups (0-9 to 50-59 years in 10-year groups, 60-64, 65-69, 70-74, and 75 years or older, the finest grouping available in every year) were applied to each district's age structure, and expected counts were rescaled each year to the observed national total [@inskip1983methods]. The ratio of observed to expected counts is the standardized treatment ratio (STR); indirectly standardized ratios compare each district with the national age profile rather than with each other. National treatment tables are not published by sex, so standardization was by age only. For national trends, annual treatment rates were also directly standardized to the 2015 national population in the same ten age groups."),
("Covariates",
 f"Before the age-standardized models were fitted, {N['n_hyp']} district characteristics were specified from the literature with an expected direction: physical activity and recreation environment (walking and moderate-or-vigorous physical activity from the Community Health Survey, and densities of public sports facilities, community gyms, swimming pools, village sports facilities, and senior leisure facilities), health behaviors and status (obesity management at national health screening, current smoking, high-risk drinking, perceived stress, and good self-rated health), social structure (older single-person households, employment rate, and regular employment), and environment and services (green area share, hospital beds, and public health center use). Five controls were forced into every model: urban population share, clinic density, sex ratio, fiscal independence, and the share of the population aged 80 years or older, because the oldest standardization group (75 years or older) cannot capture differences in very old age within it. Covariates were standardized to 1 standard deviation (SD). Missing district-years were filled within districts (Online Resource 1, Table S1)."),
("Statistical analysis",
 "Counts were modeled with a negative binomial likelihood, an offset of log expected counts, a Besag-York-Mollié 2 (BYM2) district effect with penalized-complexity priors [@riebler2016intuitive], and first-order random-walk and independent year effects, using integrated nested Laplace approximation [@rue2009approximate]. District adjacency was defined by shared polygon boundaries, with six island districts linked to their nearest neighbor; Jeju Island formed a separate component. Rate ratios (RRs) per 1 SD were judged credible when 95% credible intervals (CrIs) excluded 1. Robustness to covariate selection was assessed across 200 random covariate subsets; a covariate was classed as subset-stable if credible in at least 75% of subsets containing it with the same sign in at least 95% (study-defined thresholds) [@steegen2016increasing]. Hot and cold spots were districts with a posterior probability of a residual RR above 1 of more than 0.95 or less than 0.05, estimated for the full period and for three calendar windows (2011-2015, 2016-2019, 2020-2024). Persistence was summarized by Kendall's W of annual rankings of unsmoothed STRs and by emerging hot spot analysis (Getis-Ord Gi* with Mann-Kendall trends) of empirical Bayes-smoothed ratios [@getis1992analysis; @mann1945nonparametric]."),
("Sensitivity analyses",
 "Knorr-Held type I-IV space-time interactions were added to the principal model, with sum-to-zero constraints defined for each connected component of the adjacency graph [@knorrheld2000bayesian]. Subset-stable covariates were decomposed into district means and two-way-centered within-district deviations [@bell2015explaining]. Further analyses (Online Resource 1, Tables S2-S4) used alternative likelihoods, time effects, priors, and neighborhood definitions; an areal Spatial+-type adjustment for spatial confounding [@hodges2010adding; @dupont2022spatial]; covariates lagged by 1 or 2 years; omission of each province and each year; perturbation of imputed values; the adjacency graph without the boundary corrections; expected counts from eight age groups; and omission of the share aged 80 years or older. Treated gastric cancer and infectious diseases served as comparison outcomes, and seat-belt wearing, cardiopulmonary resuscitation awareness, and waste recycling as negative-control exposures [@lipsitch2010negative]. E-values quantified the confounding needed to explain each association [@vanderweele2017sensitivity], and posterior predictive checks assessed fit. Reporting follows STROBE and RECORD [@vonelm2007strengthening; @benchimol2015reporting]."),
]

_hot_all = N["hot_all_windows"]
RESULTS = [
("Treated persons and trends",
 f"Over 2011-2024, {N['cases_total']/1e6:.1f} million treated person-years were recorded among {N['py']/1e6:.0f} million person-years (Table 1). The crude treatment rate rose from {N['crude_2011']:,.0f} to {N['crude_2024']:,.0f} per 100,000 population ({100*(N['crude_2024']/N['crude_2011']-1):.0f}% increase, with a temporary fall in 2020), whereas the directly age-standardized rate (2015 standard population) was {N['asr_2011']:,.0f} in 2011 and {N['asr_2024']:,.0f} in 2024 (Fig. 1). The 10th-90th percentile range of district STRs was {T1['2011-2024']['sir_p10']:.2f}-{T1['2011-2024']['sir_p90']:.2f}."),
("A persistent but attenuating southern and inland concentration",
 f"Moran's I of the log STR was {N['moran_pooled']:.2f} for the pooled period; by year it was {N['moran_y'][2011]:.2f} in 2011 and {N['moran_y'][2020]:.2f} in 2020 and fell to {N['moran_y'][2024]:.2f} in 2024; the BYM2 spatial fraction was {N['phi'][0]:.2f} (95% CrI {N['phi'][1]:.2f}-{N['phi'][2]:.2f}). Residual RRs ranged from {N['rr_min']:.2f} to {N['rr_max']:.2f}, with {N['n_hot']} hot spots, mainly in {sidos(N['hot_by_sido'], 8)}, and {N['n_cold']} cold spots, mainly in {sidos(N['cold_by_sido'], 2)} (Fig. 1). Only {N['hot_capital']} hot spots but {N['cold_capital']} cold spots were in the capital region. Of the hot spots, {N['type_class']['hotspot']['county']} were rural counties (gun), {N['type_class']['hotspot']['city']} cities, and {N['type_class']['hotspot']['ward']} urban wards; {N['type_class']['hotspot']['county']} of {N['n_type']['county']} counties but {N['type_class']['hotspot']['ward']} of {N['n_type']['ward']} wards were hot spots. In all three windows, {_hot_all} districts were hot spots (Fig. 2). District rankings were stable (Kendall's W {N['kendall_W']:.2f}), and emerging hot spot analysis identified {N['ehsa']['Persistent hot']} persistent and {N['ehsa']['Intensifying hot']} intensifying hot spots, the latter mostly in mountain counties of North Jeolla, {N['ehsa']['Diminishing hot']} diminishing hot spots, mostly on the southwestern coast of South Jeolla, and {N['ehsa']['Persistent cold']} persistent cold spots in the capital region."),
("District correlates in the principal model",
 f"Adding the {N['n_hyp']} covariates improved fit over the forced controls alone (ΔWAIC {N['waic_main']-N['waic_forced']:.0f}). In the principal model, {N['n_cred_hyp']} of {N['n_hyp']} covariates were credible and {N['n_robust']} were subset-stable (Table 2). Per 1 SD, treatment was lower where public swimming pools ({ci('public_pools_per_100k')}) and village sports facilities ({ci('village_sports_facilities_per_100k')}) were denser, but higher where moderate physical activity ({ci('moderate_pa_rate')}) and walking ({ci('walking_practice_rate')}) were more common. Treatment was higher with more senior leisure facilities ({ci('older_leisure_facilities_per_1000')}), more older single-person households ({ci('older_single_household_share')}), and more public health center use ({ci('public_health_centre_use_rate')}). Among forced controls, the share aged 80 years or older ({ci('pop80_share')}), urban population share ({ci('urban_population_share')}), and sex ratio ({ci('sex_ratio')}) were inversely associated and clinic density positively ({ci('clinics_per_100k')})."),
("Space-time interaction and other sensitivity analyses",
 f"Knorr-Held type II and IV interactions, which allow district-specific trends, fitted much better than the principal model (ΔWAIC {dW('KH_typeII'):,.0f} and {dW('KH_typeIV'):,.0f}). In both, the associations with swimming pools, village sports facilities, moderate physical activity, regular employment, and hospital beds were no longer credible in the principal-model direction: in the type IV model (swimming pools {tci(S43('KH_typeIV','public_pools_per_100k'))}; moderate physical activity {tci(S43('KH_typeIV','moderate_pa_rate'))}), village sports facilities reversed direction ({tci(S43('KH_typeIV','village_sports_facilities_per_100k'))}). Senior leisure facilities ({tci(S43('KH_typeIV','older_leisure_facilities_per_1000'))}) and older single-person households ({tci(S43('KH_typeIV','older_single_household_share'))}) remained credible in both; public health center use remained credible in type II only. In the type III model, which allows no district-specific trends, seven of the eight subset-stable associations remained credible, all except moderate physical activity, and a Poisson model with an observation-level effect, which fitted about as well as type II (WAIC {N['s41_waic']['C1_poisson_lognormal']:,.0f}), retained all {N['c1_robust_kept']}. "
 f"Figure 3 compares the principal model, the type II and type IV models, and the principal model fitted to infectious diseases. When decomposed, the associations with swimming pools ({tci(N['bw']['public_pools_per_100k__within'])}), village sports facilities ({tci(N['bw']['village_sports_facilities_per_100k__within'])}), and moderate physical activity ({tci(N['bw']['moderate_pa_rate__within'])}) came from within-district deviations, whereas their between-district components were not credible (swimming pools {tci(N['bw']['public_pools_per_100k__between'])}; village sports facilities {tci(N['bw']['village_sports_facilities_per_100k__between'])}); senior leisure facilities were associated in both components. Older single-person households, observed only from 2015, had a credible within-district component ({tci(N['bw']['older_single_household_share__within'])}) but not a between-district one ({tci(N['bw']['older_single_household_share__between'])}), and the association weakened when imputed values were perturbed ({tci((N['rubin']['older_single_household_share']['IRR_pooled'], N['rubin']['older_single_household_share']['lo'], N['rubin']['older_single_household_share']['hi'], True))}; Online Resource 1, Table S2). Within the principal structure, the eight associations were retained in {min(v[0] for v in N['ret14'].values())}-{max(v[0] for v in N['ret14'].values())} of {max(v[1] for v in N['ret14'].values())} alternative specifications, in at least {min(int(LO.loc[('province', v), 'n_cred_same_sign']) for v in ROB)} of 17 leave-one-province fits, and in at least {min(int(LO.loc[('year', v), 'n_cred_same_sign']) for v in ROB)} of 14 leave-one-year fits, and were unchanged with the alternative adjacency graph, eight-group expected counts, and omission of the share aged 80 years or older (Online Resource 1, Tables S2-S3). For infectious diseases, village sports facilities ({tci(NCO('INFECT','village_sports_facilities_per_100k'))}) and senior leisure facilities ({tci(NCO('INFECT','older_leisure_facilities_per_1000'))}) showed associations in the same direction, whereas swimming pools ({tci(NCO('INFECT','public_pools_per_100k'))}) and older single-person households ({tci(NCO('INFECT','older_single_household_share'))}) showed opposite associations; for gastric cancer, senior leisure facilities ({tci(NCO('GCA','older_leisure_facilities_per_1000'))}) and public health center use ({tci(NCO('GCA','public_health_centre_use_rate'))}) were associated in the same direction. Two of three negative-control exposures were credible (seat-belt wearing {tci((N['negctl']['seatbelt_wearing_rate']['IRR'], N['negctl']['seatbelt_wearing_rate']['lo'], N['negctl']['seatbelt_wearing_rate']['hi']))}; resuscitation awareness {tci((N['negctl']['cpr_awareness_rate']['IRR'], N['negctl']['cpr_awareness_rate']['lo'], N['negctl']['cpr_awareness_rate']['hi']))}). E-values for the subset-stable associations were {min(v['E_point'] for v in N['evalue'].values()):.2f}-{max(v['E_point'] for v in N['evalue'].values()):.2f}. Posterior predictive intervals covered {100*N['ppc']['coverage95']:.1f}% (95%) and {100*N['ppc']['coverage50']:.1f}% (50%) of district-years, residual Moran's I was {N['moran_resid']:.2f}, and the structured spatial effect accounted for {100*N['varpart']['spatial_structured']['share_of_linear_predictor_var']:.0f}% and all covariates for {100*N['varpart']['fixed_covariates']['share_of_linear_predictor_var']:.0f}% of the linear predictor variance (Online Resource 1, Table S4)."),
]
